fn sum_evens(v: &Vec[Int]) -> Int {
  var total = 0;
  for n in v {
    if n % 2 == 0 {
      total = total + n;
    }
  }
  return total;
}

fn max_value(v: &Vec[Int]) -> Int {
  if v.len() == 0 { return 0; }
  var max = v[0];
  var i = 0;
  while i < v.len() {
    if v[i] > max { max = v[i]; }
    i = i + 1;
  }
  return max;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(3); v.push(1); v.push(4); v.push(1); v.push(5); v.push(9);
  return max_value(&v);
}
